-- Таблица для хранения сессий брейншторма по каждой цели.
-- Позволяет сохранять историю чата (вопросы и ответы) и отмечать избранные сообщения.

CREATE TABLE IF NOT EXISTS brainstorm_sessions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  client_uuid UUID NOT NULL REFERENCES clients(client_uuid) ON DELETE CASCADE,
  goal_id UUID NOT NULL REFERENCES goals(id) ON DELETE CASCADE,
  idea_title TEXT NOT NULL,
  idea_description TEXT,
  idea_tags TEXT[] DEFAULT '{}',
  messages JSONB NOT NULL DEFAULT '[]',
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_brainstorm_sessions_client ON brainstorm_sessions(client_uuid);
CREATE INDEX IF NOT EXISTS idx_brainstorm_sessions_goal ON brainstorm_sessions(goal_id);

CREATE OR REPLACE FUNCTION update_brainstorm_updated_at()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trg_brainstorm_updated_at ON brainstorm_sessions;
CREATE TRIGGER trg_brainstorm_updated_at
  BEFORE UPDATE ON brainstorm_sessions
  FOR EACH ROW EXECUTE FUNCTION update_brainstorm_updated_at();

